//! Protobuf messages generated by prost from `proto/*.proto`.
//!
//! The code is generated ahead of time and committed, so building this crate
//! needs neither `protoc` nor a build script. To change the messages, edit
//! the `.proto` files and run the generator (see the crate README).

#![allow(missing_docs, clippy::all, clippy::pedantic)]

pub(crate) mod tn;
pub(crate) mod tsce;
pub(crate) mod tsd;
pub(crate) mod tsp;
pub(crate) mod tst;
pub(crate) mod tswp;
